/** Wire protocol shared by host and browser halves. */
export const FILE_EXPLORER_ROUTE = '/file-explorer/api'

export interface BrowserEntry {
  name: string
  /** Workspace-relative path ('' = root). */
  path: string
  kind: 'file' | 'directory'
  size?: number
}

export type FilePreview =
  | { kind: 'text'; name: string; extension: string; content: string; size: number }
  | { kind: 'image'; name: string; mime: string; dataUrl: string; size: number }
  | { kind: 'empty'; name: string; size: 0 }
  | { kind: 'binary'; name: string; size: number }
  | { kind: 'too-large'; name: string; size: number }

export type ApiResponse =
  | { ok: true; root: string; entries: BrowserEntry[] }
  | { ok: true; preview: FilePreview }
  | { ok: true; path: string; parentPath: string }
  | { ok: false; error: string }

export interface Config {
  /** Single text-file read cap in bytes (default 2 MiB). */
  maxTextBytes?: number
  /** Single image-file read cap in bytes (default 10 MiB). */
  maxImageBytes?: number
}
